/** True when this key, pressed on this target, presses something: what a held repeat is swallowed for here, and what the
 *  dialog stack refuses behind the top dialog and in an arming beat (`modal-stack.ts`). */
export function pressesSomething(key: string, target: KeyTarget | null): boolean {
  if (key === "Enter") return !(target && (target.tag === "TEXTAREA" || target.editable));
  if (key === " ") return target !== null && spacePresses(target);
  return false;
}

/** True when this keydown is a held key's repeat that would press something — the key guard swallows it, wherever it lands. */
export function swallowsHeldKey(key: string, repeat: boolean, target: KeyTarget | null): boolean {
  return repeat && pressesSomething(key, target);
}

import { swallowsHeldKey, keyTargetOf } from "@/lib/held-key";
import {
  armBeat, closeLayer, closePlan, heirsOf, isTopLayer, nextOpenOrder, openLayer, openLayers, topOf, whereIs, type Layer,
} from "@/lib/modal-stack";
import { installKeyGuard } from "./key-guard";

const FOCUSABLE =
  'button:not([disabled]), [href], input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])';

/* ═══════════════════════════════════════════════════════════════════════════
   ⭐ S6 A8i-2 · THE DIALOG STACK, AS MODAL STANDS ON IT. The rules live in
   `modal-stack.ts`, pure; what follows reads the page for them and acts.
   ═══════════════════════════════════════════════════════════════════════════ */

/** How many frames a dialog waits for its first target to be drawn and enabled before it gives focus to its first
 *  control that can be pressed instead (`focusIn`, in Modal): about a sixth of a second. */
const FOCUS_TRIES = 10;
/** Withheld from assistive technology — a leaving dialog's ghost among it: focus there is nowhere (A8h's test,
 *  `sell-result-host.tsx`). */
const NOWHERE = "[aria-hidden='true'], [inert]";

/** Focus is "nowhere": no element, the page itself, a removed element, or withheld content. */
function isNowhere(node: unknown): boolean {
  if (!(node instanceof Element)) return true;
  return node === document.body || node === document.documentElement || !node.isConnected || node.closest(NOWHERE) !== null;
}

/** An open dropdown's combobox: it keeps focus while its list is open, so an Escape pressed there is the list's. */
function openList(node: unknown): boolean {
  return node instanceof Element && node.getAttribute("role") === "combobox" && node.getAttribute("aria-expanded") === "true";
}

/**
 * ⭐ WHERE FOCUS GOES WHEN A DIALOG CLOSES. The rule is `closePlan`, pure; this reads the page for it and does what it says.
 * 🔴 It was one line: focus back to whatever had it when the dialog opened, always. So when the win seal closed over the
 * Sell confirm, focus went back to the confirm's money button, and a second Enter about 60 ms later, meant for the seal or
 * for the next one, SOLD the ticket (W2, proven in a real browser 2026-10-07); and when a confirm's quote lapsed under the
 * seal, focus went back to the dial behind the seal's scrim, where the Enter meant for the seal opened a new confirm.
 * ⭐ Now a dialog still open whose way back lay inside the closing one takes the closing one's way back (`heirsOf`), and
 * focus moves only when it was inside the closing dialog or nowhere: back where it was when the dialog opened if that lies
 * in the dialog now on top (or nothing is open any more), else to the top dialog's own first control. Whatever takes focus
 * is armed (`ARMING_MS`): a second press a moment later presses nothing.
 */
function leave(layer: Layer) {
  const wasTop = isTopLayer(layer);
  const box = layer.root();
  closeLayer(layer);
  const rest = openLayers();
  for (const heir of heirsOf(box, rest)) heir.restoreTo = layer.restoreTo;
  const now = document.activeElement;
  const focus = box?.contains(now) ? "inside" : isNowhere(now) ? "nowhere" : "elsewhere";
  const back = layer.restoreTo instanceof HTMLElement ? layer.restoreTo : null;
  const plan = closePlan(wasTop, focus, whereIs(rest, back, isNowhere(back)));
  const top = topOf(rest);
  if (plan.move === "back") back?.focus();
  if (plan.move === "top") top?.focusIn();
  if (plan.move === "back" && plan.arm === "top") armBeat(top?.root() ?? null, performance.now());
  if (plan.arm === "back" && back) armBeat(back, performance.now());
}

const panelRef = React.useRef<HTMLDivElement>(null);
/* ⭐ S6 A8i-2 · the dialog's portal root, its scrim and its panel: what the dialog stack asks "is it in this dialog?"
   of (`modal-stack.ts`). */
const rootRef = React.useRef<HTMLDivElement>(null);
const prevFocus = React.useRef<HTMLElement | null>(null);

useModalLock(open);
React.useEffect(() => { setMounted(true); }, []);
/* ⭐ S6 A8i-2 · THE KEY GUARD STANDS WHEREVER A DIALOG CAN OPEN (`key-guard.tsx`). AppShell installs it on every player
   page; a page outside the shell (the console) gets it from the first dialog it mounts, open or not, so it already
   stands when one opens. It is installed once per page, by whichever asks first. */
React.useEffect(() => { installKeyGuard(); }, []);

React.useEffect(() => { closeOnEscRef.current = closeOnEsc; }, [closeOnEsc]);
/* ⭐ S6 A8i-2 · the dialog stack orders open dialogs by this (`modal-stack.ts`), read at opening through a ref for the
   reason the comment above `onCloseRef` gives. */
const zIndexRef = React.useRef(zIndex);
React.useEffect(() => { zIndexRef.current = zIndex; }, [zIndex]);

