const focusables = () =>
  Array.from(panelRef.current?.querySelectorAll<HTMLElement>(FOCUSABLE) ?? []);
/* ⭐ S6 A8i-2 · THIS DIALOG TAKES FOCUS ONLY WHILE IT IS THE TOP ONE, AND NEVER ON A BUTTON THAT CANNOT BE PRESSED.
   🔴 A dialog opened beneath the win seal (a bet refused while the seal was up, or a confirm opened in the seal's
   first 30 ms) took focus 30 ms later all the same, behind the seal's scrim, where the Enter meant for the seal
   retried or confirmed the bet. It now waits, and takes focus when the dialogs over it close (`leave`).
   🔴 And a first target still disabled at 30 ms (the bet confirm's Confirm, drawn disabled for a frame after a lapsed
   quote, on a slow phone) took no focus at all, which stayed on the dial behind the scrim: the target now gets a few
   frames (`FOCUS_TRIES`), and then the first control that can be pressed takes focus instead.
   Each focus given here arms the dialog's beat (`modal-stack.ts`): for its first moment a fresh press in it presses
   nothing, so a double press cannot confirm. */
let frame = 0;
const focusIn = (triesLeft: number) => {
  if (!isTopLayer(layer)) return;
  const want = initialFocusRef.current?.current ?? null;
  const ready = want !== null && want.isConnected && !want.matches(":disabled");
  if (initialFocusRef.current && !ready && triesLeft > 0) {
    frame = requestAnimationFrame(() => focusIn(triesLeft - 1));
    return;
  }
  const target = (ready ? want : null) ?? focusables()[0] ?? panelRef.current;
  target?.focus();
  armBeat(rootRef.current, performance.now());
};
// The way back is captured now, not read at cleanup time: by then the DOM may have moved on,
// and this is the element that was focused when the dialog actually opened.
const layer: Layer = {
  z: zIndexRef.current,
  seq: nextOpenOrder(),
  root: () => rootRef.current,
  restoreTo: prevFocus.current,
